// Lightweight ICS parser modeled after upstream_feeds.py.
// Parses VEVENTs into a normalised JSON shape for the frontend.

export type CalEventSource = "rules" | "external" | "adhoc";

export interface CalEvent {
  uid: string;
  summary: string;
  start: string; // ISO string (local floating)
  end: string;
  allDay: boolean;
  description?: string;
  location?: string;
  // Where the event originated. Drives the /calendar legend colouring.
  //   rules    = generated by build_calendars.py from rules.json / rotations
  //   external = mirrored from an external published ICS (iCloud, AUPFHS Outlook)
  //   adhoc    = user-created in the Buoy Add Event dialog (SQLite buoy_events)
  source?: CalEventSource;
  // Only present for adhoc events — the buoy_events.id, enabling edit/delete.
  adhocId?: number;
  // Only present for adhoc events — which category was chosen at creation.
  adhocCategory?: "oliver_work" | "oliver_personal" | "family";
  // Stage 28 — shared D&O calendar: whose event it is, and whether it is
  // information only (never busy, never gets leave-by cues).
  owner?: "oliver" | "both" | "daisy" | "unprefixed";
  infoOnly?: boolean;
  // Parser-internal recurrence data. Only consumed when a feed opts in to
  // expandRecurrence; stripped from getCachedEventsForFeeds output.
  rrule?: string;
  exdates?: number[];
  recurrenceId?: number;
  tzid?: string;
}

// UID conventions used by build_calendars.py + upstream_feeds.py.
// Classify a UID into one of the three sources for the planner colour legend.
export function classifyEventSource(uid: string): CalEventSource {
  if (!uid) return "rules";
  const u = uid.toLowerCase();
  if (u.includes("@buoy-adhoc-") || u.startsWith("buoy-adhoc-")) return "adhoc";
  if (
    u.endsWith("@marieke-icloud") ||
    u.endsWith("@family-aupfhs-outlook") ||
    u.endsWith("@upstream") ||
    u.includes("@family-aupfhs") ||
    u.includes("@marieke-icloud")
  ) {
    return "external";
  }
  return "rules";
}

function unfold(text: string): string {
  const out: string[] = [];
  for (const line of text.split(/\r?\n/)) {
    if ((line.startsWith(" ") || line.startsWith("\t")) && out.length) {
      out[out.length - 1] += line.slice(1);
    } else {
      out.push(line);
    }
  }
  return out.join("\n");
}

function unescape(s: string): string {
  return s
    .replace(/\\n/g, "\n")
    .replace(/\\,/g, ",")
    .replace(/\\;/g, ";")
    .replace(/\\\\/g, "\\");
}

function parseProperty(line: string): { name: string; params: Record<string, string>; value: string } {
  if (!line.includes(":")) return { name: line, params: {}, value: "" };
  const idx = line.indexOf(":");
  const head = line.slice(0, idx);
  const value = line.slice(idx + 1);
  const parts = head.split(";");
  const name = parts[0].toUpperCase();
  const params: Record<string, string> = {};
  for (const p of parts.slice(1)) {
    const eq = p.indexOf("=");
    if (eq >= 0) params[p.slice(0, eq).toUpperCase()] = p.slice(eq + 1);
  }
  return { name, params, value };
}

// Offset (minutes) of an IANA zone from UTC at a UTC instant.
function zoneOffsetMinutes(utcMs: number, timeZone: string): number {
  if (timeZone === "UTC") return 0;
  const dtf = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", second: "2-digit",
    hour12: false,
  });
  const parts = dtf.formatToParts(new Date(utcMs));
  const get = (t: string) => parseInt(parts.find((p) => p.type === t)?.value ?? "0", 10);
  let hh = get("hour");
  if (hh === 24) hh = 0;
  const asUtc = Date.UTC(get("year"), get("month") - 1, get("day"), hh, get("minute"), get("second"));
  return Math.round((asUtc - utcMs) / 60000);
}

// Convert a wall-clock time in `timeZone` to the true UTC instant. Iterates
// twice to settle correctly across DST cutovers.
function zonedWallClockToUtc(
  timeZone: string, y: number, m: number, d: number, hh: number, mm: number, ss: number,
): Date {
  let guess = Date.UTC(y, m - 1, d, hh, mm, ss);
  for (let i = 0; i < 2; i++) {
    const offset = zoneOffsetMinutes(guess, timeZone);
    guess = Date.UTC(y, m - 1, d, hh, mm, ss) - offset * 60000;
  }
  return new Date(guess);
}

// Stage 25.2 — Outlook publishes TZIDs as Windows zone names. Map the common
// ones to IANA. Unknown TZIDs fall back to Australia/Melbourne (the previous
// behaviour, and correct for rules-generated feeds).
const WINDOWS_TZ: Record<string, string> = {
  "utc": "UTC", "coordinated universal time": "UTC", "gmt": "UTC", "z": "UTC",
  "aus eastern standard time": "Australia/Sydney",
  "e. australia standard time": "Australia/Brisbane",
  "cen. australia standard time": "Australia/Adelaide",
  "aus central standard time": "Australia/Darwin",
  "w. australia standard time": "Australia/Perth",
  "tasmania standard time": "Australia/Hobart",
  "new zealand standard time": "Pacific/Auckland",
  "sri lanka standard time": "Asia/Colombo",
  "india standard time": "Asia/Kolkata",
  "se asia standard time": "Asia/Bangkok",
  "singapore standard time": "Asia/Singapore",
  "china standard time": "Asia/Shanghai",
  "taipei standard time": "Asia/Taipei",
  "tokyo standard time": "Asia/Tokyo",
  "korea standard time": "Asia/Seoul",
  "arabian standard time": "Asia/Dubai",
  "gmt standard time": "Europe/London",
  "greenwich standard time": "Atlantic/Reykjavik",
  "w. europe standard time": "Europe/Berlin",
  "romance standard time": "Europe/Paris",
  "central europe standard time": "Europe/Budapest",
  "central european standard time": "Europe/Warsaw",
  "gtb standard time": "Europe/Bucharest",
  "fle standard time": "Europe/Kiev",
  "e. south america standard time": "America/Sao_Paulo",
  "pacific sa standard time": "America/Santiago",
  "eastern standard time": "America/New_York",
  "central standard time": "America/Chicago",
  "mountain standard time": "America/Denver",
  "pacific standard time": "America/Los_Angeles",
  "hawaiian standard time": "Pacific/Honolulu",
};

const validZoneCache = new Map<string, boolean>();
function isValidZone(tz: string): boolean {
  if (validZoneCache.has(tz)) return validZoneCache.get(tz)!;
  let ok = false;
  try { new Intl.DateTimeFormat("en-US", { timeZone: tz }); ok = true; } catch { ok = false; }
  validZoneCache.set(tz, ok);
  return ok;
}

export function resolveTzid(tzid: string | undefined): string {
  if (!tzid) return "Australia/Melbourne";
  const t = tzid.replace(/^"|"$/g, "").trim();
  const mapped = WINDOWS_TZ[t.toLowerCase()];
  if (mapped) return mapped;
  if (t.includes("/") && isValidZone(t)) return t;
  return "Australia/Melbourne";
}

function parseDt(value: string, params: Record<string, string>): { dt: Date; allDay: boolean } {
  const isDate = params.VALUE === "DATE" || (value.length === 8 && !value.includes("T"));
  if (isDate) {
    const y = parseInt(value.slice(0, 4), 10);
    const m = parseInt(value.slice(4, 6), 10);
    const d = parseInt(value.slice(6, 8), 10);
    // All-day: keep as local-floating midnight (date-only — no TZ semantics).
    return { dt: new Date(y, m - 1, d, 0, 0, 0, 0), allDay: true };
  }
  const raw = value.endsWith("Z") ? value.slice(0, -1) : value;
  const y = parseInt(raw.slice(0, 4), 10);
  const m = parseInt(raw.slice(4, 6), 10);
  const d = parseInt(raw.slice(6, 8), 10);
  const hh = parseInt(raw.slice(9, 11), 10);
  const mm = parseInt(raw.slice(11, 13), 10);
  const ss = raw.length >= 15 ? parseInt(raw.slice(13, 15), 10) : 0;
  // Z-suffixed values are true UTC instants. Otherwise honour TZID (Windows or
  // IANA name); no TZID / unknown TZID = Australia/Melbourne wall-clock.
  const dt = value.endsWith("Z")
    ? new Date(Date.UTC(y, m - 1, d, hh, mm, ss))
    : zonedWallClockToUtc(resolveTzid(params.TZID), y, m, d, hh, mm, ss);
  return { dt, allDay: false };
}

export function parseIcs(text: string): CalEvent[] {
  const unfolded = unfold(text);
  const events: CalEvent[] = [];
  let cur: Partial<CalEvent> | null = null;

  for (const raw of unfolded.split("\n")) {
    const line = raw.trim();
    if (!line) continue;
    if (line === "BEGIN:VEVENT") {
      cur = {};
    } else if (line === "END:VEVENT") {
      if (cur && cur.summary && cur.start && cur.end) {
        events.push({
          uid: cur.uid ?? cryptoRandom(),
          summary: cur.summary,
          start: cur.start,
          end: cur.end,
          allDay: cur.allDay ?? false,
          description: cur.description,
          location: cur.location,
          ...(cur.rrule ? { rrule: cur.rrule } : {}),
          ...(cur.exdates?.length ? { exdates: cur.exdates } : {}),
          ...(cur.recurrenceId != null ? { recurrenceId: cur.recurrenceId } : {}),
          ...(cur.tzid ? { tzid: cur.tzid } : {}),
        });
      }
      cur = null;
    } else if (cur) {
      const { name, params, value } = parseProperty(line);
      if (name === "UID") cur.uid = value;
      else if (name === "SUMMARY") cur.summary = unescape(value);
      else if (name === "DESCRIPTION") cur.description = unescape(value);
      else if (name === "LOCATION") cur.location = unescape(value);
      else if (name === "DTSTART") {
        const { dt, allDay } = parseDt(value, params);
        cur.start = dt.toISOString();
        cur.allDay = allDay;
        if (!allDay && !value.endsWith("Z")) cur.tzid = resolveTzid(params.TZID);
        else if (!allDay) cur.tzid = "UTC";
      } else if (name === "RRULE") {
        cur.rrule = value;
      } else if (name === "EXDATE") {
        for (const v of value.split(",")) {
          if (!v) continue;
          try { (cur.exdates ??= []).push(parseDt(v, params).dt.getTime()); } catch { /* skip */ }
        }
      } else if (name === "RECURRENCE-ID") {
        try { cur.recurrenceId = parseDt(value, params).dt.getTime(); } catch { /* skip */ }
      } else if (name === "DTEND") {
        const { dt } = parseDt(value, params);
        cur.end = dt.toISOString();
      }
    }
  }
  return events;
}

function cryptoRandom() {
  return Math.random().toString(36).slice(2);
}

// ---- Cache ----
// Per-URL cache so multiple feeds (e.g. master ICS + AUPFHS) can coexist.
const cacheByUrl = new Map<string, { fetchedAt: number; events: CalEvent[] }>();
const TTL_MS = 15 * 60 * 1000;

export async function getCachedEvents(url: string, force = false): Promise<CalEvent[]> {
  const now = Date.now();
  const cached = cacheByUrl.get(url);
  if (!force && cached && now - cached.fetchedAt < TTL_MS) {
    return cached.events;
  }
  try {
    // Strip embedded credentials from the URL (Node's fetch rejects them) and
    // forward them as a Basic Auth header instead.
    const headers: Record<string, string> = { "User-Agent": "Buoy/1.0" };
    let cleanUrl = url;
    try {
      const parsed = new URL(url);
      if (parsed.username || parsed.password) {
        const user = decodeURIComponent(parsed.username);
        const pass = decodeURIComponent(parsed.password);
        // For raw.githubusercontent.com, fine-grained PATs work as either a
        // bearer token OR Basic auth with the PAT as the password (any user).
        // Basic auth is the most universally compatible form, so use that.
        if (user && !pass) {
          headers["Authorization"] =
            "Basic " + Buffer.from(`x-access-token:${user}`).toString("base64");
        } else {
          headers["Authorization"] =
            "Basic " + Buffer.from(`${user}:${pass}`).toString("base64");
        }
        parsed.username = "";
        parsed.password = "";
        cleanUrl = parsed.toString();
      }
    } catch {}
    const res = await fetch(cleanUrl, { headers });
    if (!res.ok) {
      throw new Error(`ICS fetch ${res.status}`);
    }
    const text = await res.text();
    const events = parseIcs(text);
    cacheByUrl.set(url, { fetchedAt: now, events });
    return events;
  } catch (err) {
    if (cached) {
      console.warn("[ics] fetch failed, using cache:", (err as Error).message);
      return cached.events;
    }
    console.warn("[ics] fetch failed, no cache:", (err as Error).message);
    return [];
  }
}

// Read-only introspection of the per-URL cache. Used by the Admin dashboard
// to surface last-fetch time + event count per feed without revealing the URL
// itself (the caller already has the URL — this just looks up cache state).
export function getIcsCacheStatus(
  url: string,
): { fetchedAt: number; eventCount: number } | null {
  const c = cacheByUrl.get(url);
  if (!c) return null;
  return { fetchedAt: c.fetchedAt, eventCount: c.events.length };
}

// Fetch and merge multiple ICS feeds. Per-feed prefixes can be supplied so
// downstream column classifiers (e.g. "[Personal] \u2026" \u2192 Oliver-All) work.
// Events with no summary or that can't be fetched are skipped silently.
export async function getCachedEventsForFeeds(
  feeds: Array<{
    url: string;
    summaryPrefix?: string;
    forceSource?: CalEventSource;
    // Stage 28 — expand RRULE series into occurrences (opt-in per feed).
    expandRecurrence?: boolean;
    // Stage 28 — tag owner/infoOnly from D:/O:/D&O: title prefixes.
    sharedOwnerPrefixes?: boolean;
  }>,
  force = false,
): Promise<CalEvent[]> {
  const all: CalEvent[] = [];
  for (const feed of feeds) {
    if (!feed.url) continue;
    let events = await getCachedEvents(feed.url, force);
    if (feed.expandRecurrence) {
      const now = Date.now();
      events = expandRecurringEvents(events, now - 90 * 86400000, now + 400 * 86400000);
    }
    if (feed.sharedOwnerPrefixes) {
      const { classifySharedOwner, isInfoOnlyOwner } = await import("./shared-calendar");
      events = events.map((e) => {
        const owner = classifySharedOwner(e.summary);
        return { ...e, owner, infoOnly: isInfoOnlyOwner(owner) };
      });
    }
    for (const raw of events) {
      const { rrule: _r, exdates: _x, recurrenceId: _rid, tzid: _tz, ...e } = raw;
      const sum = (e.summary || "").trim();
      // Determine source: explicit feed override wins; else UID classification.
      const source: CalEventSource = feed.forceSource ?? classifyEventSource(e.uid);
      let summary = sum;
      if (feed.summaryPrefix && !sum.startsWith(feed.summaryPrefix)) {
        summary = `${feed.summaryPrefix} ${sum}`.trim();
      }
      all.push({ ...e, summary, source });
    }
  }
  return all;
}

// YYYY-MM-DD in Australia/Melbourne for the given Date instant. The server
// runs in UTC, so we cannot rely on `getFullYear()` etc. directly — events are
// now stored as true UTC instants and must be projected back into AEST/AEDT
// for date-bucketing.
export function melbourneDateKey(d: Date): string {
  const dtf = new Intl.DateTimeFormat("en-CA", {
    timeZone: "Australia/Melbourne",
    year: "numeric", month: "2-digit", day: "2-digit",
  });
  // en-CA gives YYYY-MM-DD directly.
  return dtf.format(d);
}

export function eventsForDate(events: CalEvent[], date: Date): CalEvent[] {
  const target = melbourneDateKey(date);
  return events
    .filter((e) => {
      const s = new Date(e.start);
      const en = new Date(e.end);
      // All-day events are stored as local-floating midnights in UTC fields
      // (no real timezone). Read their wall-clock components from UTC fields
      // so we don't double-shift them.
      const startKey = e.allDay
        ? `${s.getUTCFullYear()}-${String(s.getUTCMonth() + 1).padStart(2, "0")}-${String(s.getUTCDate()).padStart(2, "0")}`
        : melbourneDateKey(s);
      const endKey = e.allDay
        ? `${en.getUTCFullYear()}-${String(en.getUTCMonth() + 1).padStart(2, "0")}-${String(en.getUTCDate()).padStart(2, "0")}`
        : melbourneDateKey(en);
      return startKey <= target && endKey >= target;
    })
    .sort((a, b) => +new Date(a.start) - +new Date(b.start));
}

// ---- Stage 28: recurrence expansion ----
// Supports the RRULE subset that phone calendars actually publish:
// FREQ=DAILY|WEEKLY|MONTHLY|YEARLY, INTERVAL, COUNT, UNTIL, and BYDAY for
// WEEKLY (plain day codes). EXDATE and RECURRENCE-ID overrides are honoured.
// Anything more exotic falls back to the single base occurrence.

const DAY_CODES = ["SU", "MO", "TU", "WE", "TH", "FR", "SA"];
const MAX_OCCURRENCES = 1000;

type Wall = { y: number; m: number; d: number; hh: number; mm: number; ss: number };

function wallInZone(ms: number, tz: string): Wall {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: tz, year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false,
  }).formatToParts(new Date(ms));
  const g = (t: string) => Number(parts.find((p) => p.type === t)?.value ?? "0");
  return { y: g("year"), m: g("month"), d: g("day"), hh: g("hour") % 24, mm: g("minute"), ss: g("second") };
}

function parseUntil(v: string, allDay: boolean): number {
  const raw = v.endsWith("Z") ? v.slice(0, -1) : v;
  const y = +raw.slice(0, 4), m = +raw.slice(4, 6), d = +raw.slice(6, 8);
  if (raw.length === 8) {
    // Date-only UNTIL is inclusive of that whole day.
    return allDay
      ? new Date(y, m - 1, d, 23, 59, 59).getTime()
      : zonedWallClockToUtc("Australia/Melbourne", y, m, d, 23, 59, 59).getTime();
  }
  const hh = +raw.slice(9, 11), mm = +raw.slice(11, 13), ss = +(raw.slice(13, 15) || 0);
  return Date.UTC(y, m - 1, d, hh, mm, ss);
}

export function expandRecurringEvents(events: CalEvent[], fromMs: number, toMs: number): CalEvent[] {
  // Overrides (RECURRENCE-ID) replace the matching generated occurrence.
  const overrides = new Map<string, Set<number>>();
  for (const e of events) {
    if (e.recurrenceId != null) {
      if (!overrides.has(e.uid)) overrides.set(e.uid, new Set());
      overrides.get(e.uid)!.add(e.recurrenceId);
    }
  }
  const out: CalEvent[] = [];
  for (const e of events) {
    if (!e.rrule || e.recurrenceId != null) { out.push(e); continue; }
    const occ = expandOne(e, fromMs, toMs, overrides.get(e.uid));
    out.push(...occ);
  }
  return out;
}

function expandOne(e: CalEvent, fromMs: number, toMs: number, overridden?: Set<number>): CalEvent[] {
  const rule: Record<string, string> = {};
  for (const part of (e.rrule ?? "").split(";")) {
    const [k, v] = part.split("=");
    if (k && v != null) rule[k.toUpperCase()] = v.toUpperCase();
  }
  const freq = rule.FREQ;
  const supportedKeys = new Set(["FREQ", "INTERVAL", "COUNT", "UNTIL", "WKST", "BYDAY"]);
  const unsupported = Object.keys(rule).some((k) => !supportedKeys.has(k)) ||
    (rule.BYDAY && (freq !== "WEEKLY" || /[0-9+-]/.test(rule.BYDAY))) ||
    !["DAILY", "WEEKLY", "MONTHLY", "YEARLY"].includes(freq);
  if (unsupported) return [e];

  const interval = Math.max(1, parseInt(rule.INTERVAL ?? "1", 10) || 1);
  const count = rule.COUNT ? parseInt(rule.COUNT, 10) : Infinity;
  const until = rule.UNTIL ? parseUntil(rule.UNTIL, e.allDay) : Infinity;
  const startMs = Date.parse(e.start);
  const endMs = Date.parse(e.end);
  const tz = e.tzid ?? "Australia/Melbourne";
  const base: Wall = e.allDay
    ? (() => { const d = new Date(startMs); return { y: d.getFullYear(), m: d.getMonth() + 1, d: d.getDate(), hh: 0, mm: 0, ss: 0 }; })()
    : wallInZone(startMs, tz);
  const durDays = e.allDay ? Math.max(1, Math.round((endMs - startMs) / 86400000)) : 0;
  const durMs = endMs - startMs;

  const build = (y: number, m: number, d: number): { s: number; en: number; key: string } => {
    if (e.allDay) {
      const s = new Date(y, m - 1, d).getTime();
      const en = new Date(y, m - 1, d + durDays).getTime();
      const dt = new Date(s);
      return { s, en, key: `${dt.getFullYear()}${String(dt.getMonth() + 1).padStart(2, "0")}${String(dt.getDate()).padStart(2, "0")}` };
    }
    const s = zonedWallClockToUtc(tz, y, m, d, base.hh, base.mm, base.ss).getTime();
    const w = wallInZone(s, tz);
    return { s, en: s + durMs, key: `${w.y}${String(w.m).padStart(2, "0")}${String(w.d).padStart(2, "0")}` };
  };

  // Normalise y/m/d with day overflow via Date.UTC.
  const norm = (y: number, m: number, d: number): [number, number, number] => {
    const t = new Date(Date.UTC(y, m - 1, d));
    return [t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate()];
  };
  const out: CalEvent[] = [];
  let n = 0;
  const exd = new Set(e.exdates ?? []);
  const push = (y: number, m: number, d: number): boolean => {
    const o = build(y, m, d);
    if (o.s < startMs) return true;
    if (o.s > until || n >= count || o.s > toMs || n >= MAX_OCCURRENCES) return false;
    n++;
    if (exd.has(o.s) || overridden?.has(o.s)) return true;
    if (o.en < fromMs) return true;
    out.push({
      ...e,
      uid: n === 1 && o.s === startMs ? e.uid : `${e.uid}::${o.key}`,
      start: new Date(o.s).toISOString(),
      end: new Date(o.en).toISOString(),
    });
    return true;
  };

  for (let k = 0; k < 5000; k++) {
    if (freq === "DAILY") {
      if (!push(...norm(base.y, base.m, base.d + k * interval))) break;
    } else if (freq === "WEEKLY") {
      const days = rule.BYDAY ? rule.BYDAY.split(",").map((c) => DAY_CODES.indexOf(c)).filter((i) => i >= 0) : [];
      const baseDow = new Date(Date.UTC(base.y, base.m - 1, base.d)).getUTCDay();
      if (!days.length) {
        if (!push(...norm(base.y, base.m, base.d + k * 7 * interval))) break;
        continue;
      }
      // Week starts Monday (WKST default).
      const mondayOffset = (baseDow + 6) % 7;
      const weekStart = base.d - mondayOffset + k * 7 * interval;
      const ordered = days.map((i) => (i + 6) % 7).sort((a, b) => a - b);
      let stop = false;
      for (const off of ordered) {
        if (!push(...norm(base.y, base.m, weekStart + off))) { stop = true; break; }
      }
      if (stop) break;
    } else if (freq === "MONTHLY") {
      const t = new Date(Date.UTC(base.y, base.m - 1 + k * interval, 1));
      const y = t.getUTCFullYear(), m = t.getUTCMonth() + 1;
      const dim = new Date(Date.UTC(y, m, 0)).getUTCDate();
      if (base.d > dim) continue;
      if (!push(y, m, base.d)) break;
    } else {
      const y = base.y + k * interval;
      if (base.m === 2 && base.d === 29 && new Date(Date.UTC(y, 1, 29)).getUTCMonth() !== 1) continue;
      if (!push(y, base.m, base.d)) break;
    }
  }
  return out;
}
